// The office's app glyphs with the MA mark's 3D finish (variant B, the owner's pick, Nov 12): the canvas reference.
// GENERATED by design-drafts/app-icons/final-3d/build/make_draw3d.py from final-3d/svg/*.svg. Don't edit the tables by hand.
// It replaces the per-app drawing in `web/src/canvas/glyphs.ts` (`DRAW`): `drawGlyph` calls `drawGlyph3d`, and `AppGlyph`
// (`web/src/chrome/icons.tsx`) draws through `drawGlyph` on a small canvas, so there's one copy of the shapes. The Bible's
// glyph is in `draw3d-bible.ts`, for the desk-app host's chunk.
//
// How a fill is coloured: each ramp key below gives, per theme (light, dusk, dark), the token and its stops as
// [offset, ΔL] pairs. A stop is the token with its OKLCH lightness moved by ΔL, chroma and hue kept:
// `oklch(from <token> calc(l + ΔL) c h)`. Where the browser can't parse that (`LIVE` false), `HEX` holds the same stops
// precomputed from today's tokens; regenerate them if a token changes.
// Ops, in paint order, in the glyph's 48 box:
//   [0, path, ramp, x1, y1, x2, y2]        fill with the ramp along (x1, y1) -> (x2, y2)
//   [1, path, shades, x1, y1, x2, y2]      fold shadow, linear, from the edge (x1, y1) inward; shades: '#RRGGBBAA' per theme
//   [2, path, shades, cx, cy, r0, r]       fold shadow, radial, from radius r0 out to r
//   [3, alphas, x1, y1, x2, y2]            lit edge on the path just filled: a white line inside it (alpha per theme), on
//                                          its lit side, then the body's own ramp restored on the outer rim
// No filters, masks or images: linear and radial gradients, opacity, and a clip for the lit edge.

import { ACCENTED } from '../theme/tokens';

type Ctx = CanvasRenderingContext2D | OffscreenCanvasRenderingContext2D;
export type Ramp = [string, ...number[]];
export type Op = (number | string | string[] | number[])[];
/** The tokens a glyph reads (the office's `Tokens` fits). */
export type InkTokens = { glyph: object; accent: { default: string } };

/** The fold shadow's profile, measured from the mark's own fold: [offset, share of the shadow's opacity]. */
const PROFILE = [0, 1, 0.17, 1, 0.54, 0.28, 1, 0];
/** The lit edge's run along the light: full to 15 % of the body, gone by 55 %. */
const EDGE = [0, 1, 0.15, 1, 0.55, 0];
/**
 * Whether this browser's canvas parses relative colour, decided by the canvas itself at the first paint (UI/UX's change to the
 * generated file; `CSS.supports` doesn't prove a canvas gradient takes it, and `addColorStop` throws on a colour it can't
 * parse): a scratch context's `fillStyle` takes the string or keeps what it had, and a gradient takes it as a stop. Where
 * either fails, or there's no canvas (a test in Node), every stop comes from the `hex` table.
 */
let live: boolean | undefined;
function LIVE(): boolean {
  if (live === undefined) {
    const probe = 'oklch(from #808080 calc(l + 0.1) c h)';
    try {
      const c = (typeof OffscreenCanvas !== 'undefined' ? new OffscreenCanvas(1, 1) : document.createElement('canvas')).getContext('2d') as Ctx;
      c.fillStyle = '#000';
      c.fillStyle = probe;
      live = c.fillStyle !== '#000000';
      c.createLinearGradient(0, 0, 1, 0).addColorStop(0, probe);
    } catch {
      live = false;
    }
  }
  return live;
}

/** A set of glyphs' tables: ramps by key, their fallback hexes, and every shape once. The Bible's set is its own. */
export interface Set3d { ramps: [Ramp, Ramp, Ramp][]; hex: string[][][]; paths: string[]; cache?: Path2D[] }
const path = (s: Set3d, i: number): Path2D => ((s.cache ??= [])[i] ??= new Path2D(s.paths[i]!));
const alpha = (c: string, k: number): string => c.slice(0, 7) + Math.round(parseInt(c.slice(7), 16) * k).toString(16).padStart(2, '0');

/** The token a ramp is built on: the glyph tokens, the office accent, or `ink` (an app's own, such as the Bible's Lapis). */
function token(t: InkTokens, name: string, ink?: string): string {
  return name === 'accent' ? t.accent.default : name === 'ink' ? (ink ?? t.accent.default) : (t.glyph as Record<string, string>)[name]!;
}

/** `hex` with its OKLCH lightness moved by `d`, chroma and hue kept (what `oklch(from hex calc(l + d) c h)` gives), for a browser without relative colour. */
function shiftL(hex: string, d: number): string {
  if (!d) return hex;
  const lin = (v: number): number => (v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4);
  const gam = (v: number): number => Math.round(255 * Math.min(1, Math.max(0, v <= 0.0031308 ? 12.92 * v : 1.055 * v ** (1 / 2.4) - 0.055)));
  const [r, g, b] = [1, 3, 5].map((i) => lin(parseInt(hex.slice(i, i + 2), 16) / 255)) as [number, number, number];
  const l = Math.cbrt(0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b);
  const m = Math.cbrt(0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b);
  const sx = Math.cbrt(0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b);
  const L = 0.2104542553 * l + 0.793617785 * m - 0.0040720468 * sx;
  const A = 1.9779984951 * l - 2.428592205 * m + 0.4505937099 * sx;
  const B = 0.0259040371 * l + 0.7827717662 * m - 0.808675766 * sx;
  const L2 = L + d;
  const l_ = (L2 + 0.3963377774 * A + 0.2158037573 * B) ** 3;
  const m_ = (L2 - 0.1055613458 * A - 0.0638541728 * B) ** 3;
  const s_ = (L2 - 0.0894841775 * A - 1.291485548 * B) ** 3;
  const out = [4.0767416621 * l_ - 3.3077115913 * m_ + 0.2309699292 * s_, -1.2684380046 * l_ + 2.6097574011 * m_ - 0.3413193965 * s_, -0.0041960863 * l_ - 0.7034186147 * m_ + 1.707614701 * s_];
  return '#' + out.map((v) => gam(v).toString(16).padStart(2, '0')).join('');
}

function ramp(ctx: Ctx, s: Set3d, t: InkTokens, th: number, key: number, x1: number, y1: number, x2: number, y2: number, ink?: string): CanvasGradient {
  const g = ctx.createLinearGradient(x1, y1, x2, y2);
  const [name, ...st] = s.ramps[key]![th]!;
  const hex = token(t, name, ink);
  for (let i = 0; i < st.length; i += 2) {
    const d = st[i + 1];
    g.addColorStop(st[i]!, LIVE() ? (d ? `oklch(from ${hex} calc(l + ${d}) c h)` : hex) : ACCENTED.has(t) && name !== 'default' && name !== 'soft' && name !== 'page' ? shiftL(hex, d ?? 0) : s.hex[key]![th]![i / 2]!);
  }
  return g;
}

/** Draws one glyph's ops (from set `s`) in its 48 box. `th` is the theme's index in THEME_IDS (light, dusk, dark). */
export function paint(ctx: Ctx, s: Set3d, ops: readonly Op[], t: InkTokens, th: number, ink?: string): void {
  let last: Path2D | null = null;
  let body: CanvasGradient | null = null;
  for (const op of ops) {
    const o = op as [number, number, number, number, number, number, number];
    if (o[0] === 3) {
      if (!last || !body) continue;
      const g = ctx.createLinearGradient(o[2], o[3], o[4], o[5]);
      const a = (op[1] as number[])[th]!;
      for (let i = 0; i < EDGE.length; i += 2) g.addColorStop(EDGE[i]!, `rgba(255,255,255,${a * EDGE[i + 1]!})`);
      ctx.save();
      ctx.clip(last);
      ctx.strokeStyle = g;
      ctx.lineWidth = 3.2;
      ctx.stroke(last);
      ctx.strokeStyle = body;
      ctx.lineWidth = 1.5;
      ctx.stroke(last);
      ctx.restore();
      continue;
    }
    const p = path(s, o[1]);
    if (o[0] === 0) {
      body = ramp(ctx, s, t, th, o[2], o[3], o[4], o[5], o[6], ink);
      ctx.fillStyle = body;
      last = p;
    } else {
      const c = (op[2] as string[])[th]!;
      const g = o[0] === 1 ? ctx.createLinearGradient(o[3], o[4], o[5], o[6]) : ctx.createRadialGradient(o[3], o[4], 0, o[3], o[4], o[6]);
      for (let i = 0; i < PROFILE.length; i += 2) {
        const at = o[0] === 1 ? PROFILE[i]! : (o[5] + PROFILE[i]! * (o[6] - o[5])) / o[6];
        g.addColorStop(at, alpha(c, PROFILE[i + 1]!));
      }
      ctx.fillStyle = g;
    }
    ctx.fill(p);
  }
}

