/** At this size and under (CSS px), a glyph draws its 24 px cut. */
export const SMALL_CUT = 30;

/** For `drawGlyph`: core app `app` at `size` px at the origin, theme index `th` (THEME_IDS order). */
export function drawGlyph3d(ctx: Ctx, app: string, t: InkTokens, th: number, size: number): void {
  const g = GLYPHS_3D[app];
  if (!g) return;
  const k = size / 48;
  ctx.save();
  ctx.scale(k, k);
  paint(ctx, CORE, g[size <= SMALL_CUT ? 1 : 0], t, th);
  ctx.restore();
}
